<?php

# @autogenerated
declare(strict_types=1);

namespace Civi\Lughauth\Features\Oidc\Registration\Application\Usecase\DeleteClientRegistration;

use Civi\Lughauth\Features\Oidc\Registration\Domain\Gateway\ClientRegistrationGateway;
use Civi\Lughauth\Features\Oidc\Registration\Domain\Exception\RegistrationException;

final class DeleteClientRegistrationUsecase
{
    public function __construct(
        private readonly ClientRegistrationGateway $gateway,
    ) {
    }

    public function delete(string $clientId, string $registrationAccessToken): void
    {
        $deleted = $this->gateway->delete($clientId, $registrationAccessToken);
        if (!$deleted) {
            throw RegistrationException::invalidToken();
        }
    }
}
